// The book's practice server: a small local stand-in for the Claude API.
//
// It speaks the same format as the real Messages API (requests, responses,
// streaming events, tool use, errors, usage), so the official SDK talks to
// it unchanged. Its answers are NOT generated by a model: they come from the
// project's practice.json, a script of replies written for each chapter.
// Use it to learn the API's shape for free and offline; point the SDK at the
// real API, with your own key, to see what Claude actually answers.
//
// Run:  node practice/server.mjs        (listens on 127.0.0.1:4141)
// Then: ANTHROPIC_BASE_URL=http://127.0.0.1:4141 ANTHROPIC_API_KEY=test-key
import crypto from "node:crypto";
import fs from "node:fs";
import http from "node:http";

const PORT = Number(process.env.PRACTICE_PORT ?? 4141);
const KEY = "test-key";
const MIN_CACHE = 1024; // the smallest prefix that is cached, in tokens

// The models the practice server knows, with their limits (from the Models
// API documentation of November 2026; the real list changes, ask
// GET /v1/models on the real API).
const MODELS = [
  ["claude-fable-5-2", "Claude Fable 5.2", 1_000_000, 128_000],
  ["claude-opus-5-5", "Claude Opus 5.5", 1_000_000, 128_000],
  ["claude-sonnet-5-5", "Claude Sonnet 5.5", 1_000_000, 128_000],
  ["claude-haiku-5-5", "Claude Haiku 5.5", 1_000_000, 128_000],
  ["claude-opus-4-8", "Claude Opus 4.8", 1_000_000, 128_000],
  ["claude-haiku-4-5", "Claude Haiku 4.5", 200_000, 64_000],
];
// Models on which thinking cannot be turned off, and forced tool choice is rejected.
const ALWAYS_THINKING = new Set(["claude-fable-5-2", "claude-opus-5-5"]);
const NO_FORCED_TOOLS = new Set(["claude-fable-5-2", "claude-opus-5-5", "claude-sonnet-5-5"]);

const script = () => JSON.parse(fs.readFileSync("practice.json", "utf8"));
const cache = new Map(); // prefix hash -> tokens
const failures = new Map(); // rule index -> times it has failed so far
let counter = 0;

// About four characters per token in English and two in Arabic: an
// approximation; the real count comes from the model's tokenizer (POST
// /v1/messages/count_tokens). An image counts about width x height / 750
// tokens, and a PDF page about 1,500.
function tokens(value) {
  const text = JSON.stringify(value ?? "", media);
  const other = text.replace(/[\x00-\x7f]/g, "").length;
  return Math.ceil((text.length - other) / 4 + other / 2);
}

function media(key, value) {
  if (value?.type === "image" && value.source?.type === "base64") {
    const png = Buffer.from(value.source.data, "base64");
    const [w, h] = png.length > 24 ? [png.readUInt32BE(16), png.readUInt32BE(20)] : [1000, 1000];
    return "x".repeat(Math.ceil((Math.min(w, 1568) * Math.min(h, 1568)) / 750) * 4);
  }
  if (value?.type === "document" && value.source?.type === "base64") {
    const pdf = Buffer.from(value.source.data, "base64").toString("latin1");
    const pages = (pdf.match(/\/Type\s*\/Page[^s]/g) ?? [1]).length;
    return "x".repeat(pages * 1500 * 4);
  }
  return value;
}

const IMAGE_TYPES = ["image/jpeg", "image/png", "image/gif", "image/webp"];

// Images and documents must say what they are, and be what they say.
function badMedia(messages) {
  for (const [i, m] of messages.entries()) {
    for (const [j, b] of (Array.isArray(m.content) ? m.content : []).entries()) {
      const where = `messages.${i}.content.${j}`;
      if (b.type === "image" && b.source?.type === "base64") {
        if (!IMAGE_TYPES.includes(b.source.media_type)) {
          return `${where}.source.media_type: must be one of ${IMAGE_TYPES.join(", ")}`;
        }
        const head = Buffer.from(b.source.data, "base64").subarray(0, 4).toString("latin1");
        const real = head.startsWith("\x89PNG") ? "image/png" : head.startsWith("\xff\xd8") ? "image/jpeg" : null;
        if (real && real !== b.source.media_type) {
          return `${where}.source: the image data is ${real}, but media_type says ${b.source.media_type}`;
        }
      }
      if (b.type === "document" && b.source?.type === "base64") {
        if (b.source.media_type !== "application/pdf") return `${where}.source.media_type: must be application/pdf`;
        if (!Buffer.from(b.source.data, "base64").toString("latin1").startsWith("%PDF")) {
          return `${where}.source.data: not a PDF`;
        }
      }
    }
  }
  return "";
}

function textOf(content) {
  if (typeof content === "string") return content;
  return content.filter((b) => b.type === "text").map((b) => b.text).join("\n");
}

function error(res, status, type, message, headers = {}) {
  const id = `req_practice_${String(++counter).padStart(4, "0")}`;
  res.writeHead(status, {"content-type": "application/json", "request-id": id, ...headers});
  res.end(JSON.stringify({type: "error", error: {type, message}, request_id: id}));
}

function invalid(body, counting) {
  if (!body.model) return "model: Field required";
  if (!MODELS.some(([id]) => id === body.model)) return null; // reported as 404
  if (body.max_tokens === undefined && !counting) return "max_tokens: Field required";
  if (!Array.isArray(body.messages) || body.messages.length === 0) return "messages: at least one message is required";
  if (body.messages[0].role !== "user") return "messages: the first message must use the \"user\" role";
  const media = badMedia(body.messages);
  if (media) return media;
  if (ALWAYS_THINKING.has(body.model) && body.thinking && body.thinking.type !== "adaptive") {
    return `thinking: type "${body.thinking.type}" is not supported for this model; use "adaptive" or omit it`;
  }
  if (NO_FORCED_TOOLS.has(body.model) && ["any", "tool"].includes(body.tool_choice?.type)) {
    return "tool_choice: type \"tool\" and \"any\" are not supported for this model.";
  }
  if (body.max_tokens > MODELS.find(([id]) => id === body.model)[3]) {
    return `max_tokens: ${body.max_tokens} > ${MODELS.find(([id]) => id === body.model)[3]}, the maximum for ${body.model}`;
  }
  return "";
}

// The reply for a request: the first rule of practice.json that matches.
function reply(body) {
  const last = body.messages.at(-1);
  const results = Array.isArray(last.content) ? last.content.filter((b) => b.type === "tool_result") : [];
  const asked = textOf(last.content).toLowerCase();
  const system = textOf(body.system ?? "").toLowerCase();
  const rules = script().replies;
  for (const [i, rule] of rules.entries()) {
    const when = rule.when ?? {};
    const w = typeof when === "string" ? {text: when} : when;
    if (w.text && !asked.includes(w.text.toLowerCase())) continue;
    if (w.system && !system.includes(w.system.toLowerCase())) continue;
    if (w.tool_result && !results.some((r) => r.tool_use_id.includes(w.tool_result))) continue;
    if (w.tools === false && body.tools?.length) continue;
    if (w.tools === true && !body.tools?.length) continue;
    if (w.model && body.model !== w.model) continue;
    if (w.history !== undefined && w.history !== body.messages.length > 1) continue;
    if (w.document && !JSON.stringify(last.content).includes(`"title":"${w.document}"`)) continue;
    if (w.allowed_domains !== undefined && w.allowed_domains !== Boolean(searchTool(body)?.allowed_domains)) continue;
    if (rule.error) {
      const failed = failures.get(i) ?? 0;
      if (failed >= (rule.error.times ?? Infinity)) continue;
      failures.set(i, failed + 1);
    }
    return rule;
  }
  return {text: "(practice server: no reply in practice.json matches this request)"};
}

const searchTool = (body) => (body.tools ?? []).find((t) => t.type?.startsWith("web_search"));

// The web search tool's allowed_domains: results from other sites are dropped.
function restrict(blocks, body) {
  const allowed = searchTool(body)?.allowed_domains;
  if (!allowed) return blocks;
  const ok = (url) => allowed.some((d) => new URL(url).hostname === d || new URL(url).hostname.endsWith(`.${d}`));
  return blocks.map((b) => (b.type === "web_search_tool_result" && Array.isArray(b.content)
    ? {...b, content: b.content.filter((r) => ok(r.url))} : b));
}

function blocksOf(rule, body) {
  return restrict(blocksFrom(rule, body), body);
}

function blocksFrom(rule, body) {
  if (rule.blocks) {
    return rule.blocks.map((b, i) => (b.type === "tool_use" ? {id: `toolu_practice_${b.name}_${counter}_${i}`, ...b} : b));
  }
  if (rule.json !== undefined) return [{type: "text", text: JSON.stringify(rule.json)}];
  return [{type: "text", text: rule.text}];
}

// Prompt caching: the prefix up to the last cache_control breakpoint (or the
// whole request with top-level cache_control) is cached once it is large
// enough, and read back by a later request that starts with the same bytes.
function caching(body) {
  const parts = [body.tools ?? [], body.system ?? "", ...body.messages];
  let end = body.cache_control ? parts.length : -1;
  const marked = (v) => JSON.stringify(v).includes("\"cache_control\"");
  if (end < 0) parts.forEach((p, i) => { if (marked(p)) end = i + 1; });
  const total = tokens(parts);
  if (end < 0) return {input_tokens: total, cache_creation_input_tokens: 0, cache_read_input_tokens: 0};
  const prefix = JSON.stringify([body.model, parts.slice(0, end)]);
  const size = tokens(parts.slice(0, end));
  if (size < MIN_CACHE) return {input_tokens: total, cache_creation_input_tokens: 0, cache_read_input_tokens: 0};
  const key = crypto.createHash("sha256").update(prefix).digest("hex");
  if (cache.has(key)) return {input_tokens: total - size, cache_creation_input_tokens: 0, cache_read_input_tokens: size};
  cache.set(key, size);
  return {input_tokens: total - size, cache_creation_input_tokens: size, cache_read_input_tokens: 0};
}

function message(body) {
  const rule = reply(body);
  if (rule.error) return {rule};
  const content = blocksOf(rule, body);
  const stop = rule.stop_reason ?? (content.some((b) => b.type === "tool_use") ? "tool_use" : "end_turn");
  let out = tokens(content);
  if (out > body.max_tokens) {
    out = body.max_tokens;
    const first = content.find((b) => b.type === "text");
    if (first) first.text = first.text.slice(0, body.max_tokens * 4);
    return {rule, msg: build(body, content, "max_tokens", out, rule)};
  }
  return {rule, msg: build(body, content, stop, out, rule)};
}

function build(body, content, stop, out, rule = {}) {
  return {
    id: `msg_practice_${String(++counter).padStart(4, "0")}`,
    type: "message",
    role: "assistant",
    model: body.model,
    content,
    stop_reason: stop,
    stop_sequence: null,
    stop_details: null,
    usage: {...caching(body), output_tokens: out, ...(rule.usage ?? {})},
  };
}

function stream(res, msg) {
  res.writeHead(200, {"content-type": "text/event-stream", "request-id": `req_practice_${counter}`});
  const send = (type, data) => res.write(`event: ${type}\ndata: ${JSON.stringify({type, ...data})}\n\n`);
  send("message_start", {message: {...msg, content: [], stop_reason: null, usage: {...msg.usage, output_tokens: 1}}});
  msg.content.forEach((block, index) => {
    if (block.type === "text") {
      send("content_block_start", {index, content_block: {type: "text", text: ""}});
      for (const piece of block.text.match(/\S+\s*|\s+/g) ?? []) {
        send("content_block_delta", {index, delta: {type: "text_delta", text: piece}});
      }
    } else if (block.type === "tool_use") {
      send("content_block_start", {index, content_block: {...block, input: {}}});
      const json = JSON.stringify(block.input);
      for (let i = 0; i < json.length; i += 16) {
        send("content_block_delta", {index, delta: {type: "input_json_delta", partial_json: json.slice(i, i + 16)}});
      }
    }
    send("content_block_stop", {index});
  });
  send("message_delta", {delta: {stop_reason: msg.stop_reason, stop_sequence: null}, usage: {output_tokens: msg.usage.output_tokens}});
  send("message_stop", {});
  res.end();
}

function models(res, id) {
  const all = MODELS.map(([model, name, input, output]) => ({
    type: "model", id: model, display_name: name, created_at: "2026-11-01T00:00:00Z",
    max_input_tokens: input, max_tokens: output,
  }));
  if (id) {
    const one = all.find((m) => m.id === id);
    if (!one) return error(res, 404, "not_found_error", `model: ${id}`);
    return json(res, one);
  }
  json(res, {data: all, has_more: false, first_id: all[0].id, last_id: all.at(-1).id});
}

function json(res, value) {
  res.writeHead(200, {"content-type": "application/json", "request-id": `req_practice_${++counter}`});
  res.end(JSON.stringify(value));
}

const server = http.createServer((req, res) => {
  let raw = "";
  req.on("data", (chunk) => (raw += chunk));
  req.on("end", () => {
    const key = req.headers["x-api-key"] ?? req.headers.authorization?.replace(/^Bearer /, "");
    if (key !== KEY) {
      return error(res, 401, "authentication_error", "invalid x-api-key");
    }
    const url = new URL(req.url, "http://localhost");
    if (req.method === "GET" && url.pathname.startsWith("/v1/models")) {
      return models(res, decodeURIComponent(url.pathname.split("/")[3] ?? ""));
    }
    if (req.method !== "POST" || !url.pathname.startsWith("/v1/messages")) {
      return error(res, 404, "not_found_error", `${req.method} ${url.pathname}`);
    }
    let body;
    try {
      body = JSON.parse(raw);
    } catch {
      return error(res, 400, "invalid_request_error", "the request body is not valid JSON");
    }
    const version = req.headers["anthropic-version"] ?? "2023-06-01";
    const sampling = ["temperature", "top_p", "top_k"].find((k) => k in body);
    if (sampling && version >= "2026-10-21") {
      return error(res, 400, "invalid_request_error", `${sampling}: not supported in API version ${version}`);
    }
    const problem = invalid(body, url.pathname === "/v1/messages/count_tokens");
    if (problem === null) return error(res, 404, "not_found_error", `model: ${body.model}`);
    if (problem) return error(res, 400, "invalid_request_error", problem);
    if (url.pathname === "/v1/messages/count_tokens") {
      return json(res, {input_tokens: tokens([body.tools ?? [], body.system ?? "", ...body.messages])});
    }
    const {rule, msg} = message(body);
    if (rule.error) {
      const {status, type, message: text, retry_after: after} = rule.error;
      return error(res, status, type, text, after ? {"retry-after": String(after)} : {});
    }
    fs.appendFileSync("practice.log", `${msg.id} ${body.model} ${msg.stop_reason} in=${msg.usage.input_tokens} out=${msg.usage.output_tokens}\n`);
    return body.stream ? stream(res, msg) : json(res, msg);
  });
});

server.listen(PORT, "127.0.0.1", () => console.log(`practice server on http://127.0.0.1:${PORT}`));
